"""sklearn.utils.fixes — compatibility shims for older numpy / scipy."""

import numpy as _np


def parse_version(v):
    """Best-effort version parse."""
    try:
        from packaging.version import parse
        return parse(v)
    except Exception:
        return v


sp_version = parse_version(_np.__version__)
np_version = sp_version


def percentile(a, q, axis=None, keepdims=False, weights=None,
                method='linear'):
    """Wrapper around ``np.percentile`` with weight support."""
    if weights is None:
        return _np.percentile(a, q, axis=axis, keepdims=keepdims, method=method)
    # Weighted percentile — sort + cumulative weights.
    a = _np.asarray(a); w = _np.asarray(weights)
    order = _np.argsort(a)
    cw = _np.cumsum(w[order])
    target = q / 100.0 * cw[-1]
    return a[order][_np.searchsorted(cw, target)]


def delayed(func):
    """Decorator placeholder — joblib's delayed builds a deferred call."""
    try:
        from joblib import delayed as _d
        return _d(func)
    except Exception:
        def _wrap(*args, **kwargs):
            return func, args, kwargs
        return _wrap


def threadpool_limits(*args, **kwargs):
    """Stub for thread-pool limiting — passthrough."""
    try:
        from threadpoolctl import threadpool_limits as _tpl
        return _tpl(*args, **kwargs)
    except Exception:
        import contextlib
        return contextlib.nullcontext()


def threadpool_info():
    try:
        from threadpoolctl import threadpool_info as _tpi
        return _tpi()
    except Exception:
        return []


def _IS_32BIT():
    return _np.dtype('intp').itemsize == 4


def _in_unstable_openblas_configuration():
    return False


def _is_pandas_df(X):
    try:
        import pandas
        return isinstance(X, pandas.DataFrame)
    except Exception:
        return False


def _take_along_axis(arr, indices, axis):
    return _np.take_along_axis(arr, indices, axis=axis)


def trapezoid(y, x=None, dx=1.0, axis=-1):
    """Numpy's trapezoid (renamed from trapz in numpy 2.0)."""
    if hasattr(_np, 'trapezoid'):
        return _np.trapezoid(y, x=x, dx=dx, axis=axis)
    return _np.trapz(y, x=x, dx=dx, axis=axis)


def _smallest_admissible_index_dtype(*arrays):
    return _np.int64


